import sys

lines = [ln.strip() for ln in sys.stdin.read().splitlines() if ln.strip()]
n = int(lines[0])
tools = {}
for i in range(1, n + 1):
    parts = lines[i].split()
    params = []
    for p in parts[1:]:
        pname, _, ptype = p.partition(':')
        params.append((pname, ptype))
    tools[parts[0]] = params

call = lines[n + 1].split()
name = call[0]
args = {}
for item in call[1:]:
    key, _, value = item.partition('=')
    args[key] = value

def matches(value, ptype):
    if ptype == 'int':
        body = value[1:] if value.startswith('-') else value
        return body.isdigit() and body != ''
    if ptype == 'float':
        try:
            float(value)
            return True
        except ValueError:
            return False
    return value != ''

if name not in tools:
    print('INVALID unknown tool')
else:
    reason = None
    for pname, ptype in tools[name]:
        if pname not in args:
            reason = f'missing {pname}'
            break
        if not matches(args[pname], ptype):
            reason = f'bad type {pname}'
            break
    print(f'INVALID {reason}' if reason else f'VALID {name}')
